<template>
  <el-drawer v-model="visible" title="模型与 OCR 调用核对" size="min(1100px,95vw)">
    <el-alert title="核对以供应商账单或调用回执为依据。页面权限不扩大平台管理员身份；最终由后台判定。" type="info" :closable="false" class="ps-section"/>
    <el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button :loading="loading" @click="refresh">刷新未确认调用</el-button>
    <h3>模型调用</h3><el-table :data="modelCalls" v-loading="loading"><el-table-column prop="id" label="调用 ID" min-width="220"/><el-table-column prop="userId" label="用户" width="100"/><el-table-column prop="scope" label="用途" width="110"/><el-table-column prop="status" label="状态" width="130"/><el-table-column prop="reason" label="原因" min-width="200"/><el-table-column prop="createdAt" label="时间" min-width="180"/><el-table-column label="操作" width="120"><template #default="{row}"><el-button v-hasPermi="['paismart:operation:execute']" link @click="edit(row,'MODEL')">核对用量</el-button></template></el-table-column></el-table>
    <h3>OCR 调用</h3><el-table :data="ocrCalls" v-loading="loading"><el-table-column prop="id" label="调用 ID" min-width="220"/><el-table-column prop="documentId" label="文档 ID" min-width="220"/><el-table-column prop="contentVersion" label="内容版本" width="100"/><el-table-column prop="state" label="状态" width="130"/><el-table-column prop="providerRequestId" label="供应商请求 ID" min-width="220"/><el-table-column prop="createdAt" label="时间" min-width="180"/><el-table-column label="操作" width="120"><template #default="{row}"><el-button v-hasPermi="['paismart:operation:execute']" link @click="edit(row,'OCR')">核对计费页</el-button></template></el-table-column></el-table>
    <h3>OCR 配置与真实测试</h3><pre class="ps-pre">{{health?JSON.stringify(health,null,2):'未返回配置状态'}}</pre>
    <input type="file" accept="image/png,image/jpeg" aria-label="OCR 健康测试图片" @change="choose"/><p class="ps-muted">选择不超过 10 MiB 的单张图片；真实测试会向供应商发出一次请求，并可能计费。</p><el-button v-hasPermi="['paismart:provider:test']" :disabled="!file" :loading="saving" @click="test">执行真实 OCR 测试</el-button><pre v-if="testResult" class="ps-pre">{{JSON.stringify(testResult,null,2)}}</pre>
    <el-dialog v-model="formOpen" title="核对供应商实际用量" width="580px" append-to-body><p>调用 {{selected?.id}}</p><el-form label-width="120px"><el-form-item :label="kind==='OCR'?'实际计费页数':'实际 Token'" required><el-input-number v-model="actual" :min="0" :max="kind==='OCR'?1:1000000000000" :precision="0"/></el-form-item><el-form-item label="账单核对依据" required><el-input v-model="reason" type="textarea" maxlength="500"/></el-form-item></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><template #footer><el-button @click="formOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">确认核对</el-button></template></el-dialog>
  </el-drawer>
</template>
<script setup lang="ts">
import {computed,ref,shallowRef,watch} from 'vue'
import {ElMessageBox} from 'element-plus'
import {ocrHealth,reconcileModelCall,reconcileOcrCall,testOcrHealth,unresolvedModelCalls,unresolvedOcrCalls} from '@/api/paismart/operations'
import {newKey} from '@/api/paismart/client'
import {errorText} from '../../composables/usePage'
const props=defineProps<{modelValue:boolean}>(),emit=defineEmits<{'update:modelValue':[boolean]}>(),visible=computed({get:()=>props.modelValue,set:v=>emit('update:modelValue',v)})
const modelCalls=shallowRef<Record<string,unknown>[]>([]),ocrCalls=shallowRef<Record<string,unknown>[]>([]),health=shallowRef<Record<string,unknown>>(),selected=shallowRef<Record<string,unknown>>(),testResult=shallowRef<Record<string,unknown>>(),file=shallowRef<File>(),loading=ref(false),saving=ref(false),error=ref(''),formError=ref(''),formOpen=ref(false),kind=ref('MODEL'),actual=ref(0),reason=ref('');let testKey=newKey()
async function refresh(){loading.value=true;error.value='';const results=await Promise.allSettled([unresolvedModelCalls(),unresolvedOcrCalls(),ocrHealth()]);if(results[0].status==='fulfilled')modelCalls.value=results[0].value.rows;if(results[1].status==='fulfilled')ocrCalls.value=results[1].value.rows;if(results[2].status==='fulfilled')health.value=results[2].value.data;error.value=results.filter(r=>r.status==='rejected').map(r=>errorText((r as PromiseRejectedResult).reason)).join('；');loading.value=false}
function edit(row:Record<string,unknown>,type:string){selected.value=row;kind.value=type;actual.value=0;reason.value='';formError.value='';formOpen.value=true}
async function save(){if(!selected.value||!reason.value.trim()){formError.value='请填写供应商实际用量与核对依据';return}saving.value=true;formError.value='';try{if(kind.value==='OCR')await reconcileOcrCall(String(selected.value.id),actual.value,reason.value.trim());else await reconcileModelCall(String(selected.value.id),actual.value,reason.value.trim());formOpen.value=false;await refresh()}catch(e){formError.value=errorText(e)}finally{saving.value=false}}
function choose(event:Event){file.value=(event.target as HTMLInputElement).files?.[0];testKey=newKey();testResult.value=undefined}
async function test(){if(!file.value)return;if(file.value.size>10*1024*1024){error.value='图片超过 10 MiB';return}try{await ElMessageBox.confirm('真实 OCR 测试将向供应商发送所选图片，可能产生一页计费。','确认真实测试',{type:'warning'});saving.value=true;testResult.value=(await testOcrHealth(file.value,testKey)).data;await refresh()}catch(e){if(e!=='cancel'&&e!=='close')error.value=errorText(e)}finally{saving.value=false}}
watch(()=>props.modelValue,open=>{if(open)void refresh()})
</script>
